/bin/bash -lc "samtools view variant.status.q1.bam chrX:154398500-154398500 | awk -v target=154398500 '
function cigar_base(pos,cigar,seq,qual,    ref,read,n,num,op,i,c,q,b) {
  ref=pos; read=1; num=\"\";
  for (i=1; i<=length(cigar); i++) {
    c=substr(cigar,i,1);
    if (c ~ /[0-9]/) { num=num c; continue; }
    n=num+0; num=\"\"; op=c;
    if (op ~ /[M=X]/) {
      if (target >= ref && target < ref+n) {
        q=read + (target-ref);
        return substr(seq,q,1) \":\" (and(16,"'$2)?"-":"+") ":" (and(1024,$2)?"dup":"nodup") ":" (and(256,$2)?"sec":"pri") ":" (and(2048,$2)?"supp":"main") ":" $5 ":" (ord(substr(qual,q,1))-33);
      }
      ref+=n; read+=n;
    } else if (op ~ /[DN]/) ref+=n;
    else if (op ~ /[IS]/) read+=n;
    else if (op == "H" || op == "P") ;
  }
  return "NA";
}
function ord(ch,    i) { return index(" !'"\\\"#"'$%&'"'\"'\"'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]"'^_`abcdefghijklmnopqrstuvwxyz{|}~", ch); }
{ print $1, $2, $4, $6, cigar_base($4,$6,$10,$11); }'"' | sort | tee target_read_bases.tsv | awk '{split("'$5,a,":"); key=a[1]":"a[2]":"a[3]":"a[4]":"a[5]; count[key]++} END{for (k in count) print k,count[k]}'"' | sort"

/bin/bash -lc "samtools view variant.status.q1.bam chrX:154398500-154398500 | perl -lane '
"'$t=154398500; ($qname,$flag,$rname,$pos,$mapq,$cigar,undef,undef,undef,$seq,$qual)=@F;
$ref=$pos; $read=0; $base="NA"; $bq="NA";
while ($cigar =~ /('"\\d+)([MIDNSHP=X])/g) {
  ("'$n,$op)=($1,$2);
  if ($op =~ /[M=X]/) {
    if ($t >= $ref && $t < $ref+$n) { $idx=$read+($t-$ref); $base=substr($seq,$idx,1); $bq=ord(substr($qual,$idx,1))-33; last; }
    $ref += $n; $read += $n;
  } elsif ($op =~ /[DN]/) { $ref += $n; }
  elsif ($op =~ /[IS]/) { $read += $n; }
}
$strand=($flag & 16) ? "-" : "+"; $dup=($flag & 1024) ? "dup" : "nodup"; $sec=($flag & 256) ? "sec" : "pri"; $supp=($flag & 2048) ? "supp" : "main";
print join("'"\\t\","'$qname,$flag,$pos,$cigar,$base,$strand,$dup,$sec,$supp,$mapq,$bq);
'"' | sort | tee target_read_bases.tsv | perl -lane '"'$k=join(":",@F[4..8]); $c{$k}++; END{for $k (sort keys %c){print "$k'"\\t"'$c{$k}"}}'"'"
